mapper.insert:
INSERT INTO clothes_images (
  clothes_id, file_id, created_at, created_by
) VALUES (
  #{clothesId}, #{fileId}, CURRENT_TIMESTAMP, #{createdBy}
)

mapper.delete:
DELETE FROM clothes_images
WHERE clothes_id = #{clothesId}
AND file_id = #{fileId}

mapper.update:
UPDATE clothes
SET 
  is_active = 'N',
  updated_at = CURRENT_TIMESTAMP,
  updated_by = #{updatedBy}
WHERE clothes_id = #{clothesId}

UPDATE clothes
SET 
  wear_count = wear_count + 1,
  updated_at = CURRENT_TIMESTAMP,
  updated_by = #{userId}
WHERE clothes_id = #{clothesId}

UPDATE clothes
SET 
  wear_count = wear_count - 1,
  updated_at = CURRENT_TIMESTAMP,
  updated_by = #{userId}
WHERE clothes_id IN (
  SELECT clothes_id 
  FROM dailylook_items 
  WHERE dailylook_id = #{dailylookId}
)

UPDATE clothes
SET 
  last_worn_date = (
    SELECT MAX(wear_date) 
    FROM dailylook_items 
    WHERE clothes_id = #{clothesId}
    AND TRUNC(wear_date) < TRUNC(SYSDATE + 1)
  ),
  updated_at = CURRENT_TIMESTAMP,
  updated_by = #{userId}
WHERE clothes_id = #{clothesId}
